UPDATE lessons SET title='Year 3, Week 2, Lesson 1: Story elements: character, setting and plot', data=json_patch(data,'{"child_mission":"Recognise how characters, settings and connected events create a complete narrative.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. In \"The koala waited for rain\", name the character and one likely goal.\nCOMPARE: The koala is the character; it may need water or cooler weather. The goal is an inference, not a fact unless the text says so.\n2. Find a place and time clue in \"At midnight, lanterns glowed outside the campsite\".\nCOMPARE: At midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere.\n3. Explain why this event follows the first: \"A storm snapped the tent rope. Dad grabbed the spare rope.\"\nCOMPARE: Dad acts because the storm damaged the rope; the second event responds to the problem.\n4. Identify character, setting and connected events: \"At the fair, Anya dropped her ticket but found it under a bench.\"\nCOMPARE: Anya is the character; the fair is the setting; she loses then finds her ticket. The loss causes the search.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nRead this original text: \"At the town garden, Noor planted a sunflower seed. A curious crow uncovered it. Noor placed smooth stones around the pot, and the seed stayed safe.\" Identify the character, place, problem, response and ending; quote one phrase as evidence for each. Write a new four-sentence story where the setting changes what the character must do.","interactive_activities":null,"learning_area":"English","learning_intention":"Recognise how characters, settings and connected events create a complete narrative.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-RECOM-01"],"parent_notes":"Parent: Marking guidance: Model identification: Noor; town garden; crow uncovered seed; stones around pot; seed remained safe. New story must have own character, clear setting and linked beginning/problem/action/end. Accept plausible original solutions where the text supports them; require the learner to explain at least one independent choice.\n\nParent: Written model 1: Original demonstration: In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision to search starts the action.\n\nParent: Written model 2: Common error: If events could be shuffled with no effect, explain what links them. Correction: Dad acts because the storm damaged the rope; the second event responds to the problem.\n\nParent: Assess comprehension and language rather than penalising speech or motor difficulties unrelated to the objective. Keep written models out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"A character is a person, animal or imagined being who takes part in a story. Look for what a character wants and does, not only a name. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["A character is a person, animal or imagined being who takes part in a story. Look for what a character wants and does, not only a name.","A narrator and a character are not automatically the same person.","Ignore the words and invent a more exciting event.","Copy the model word-for-word and call that independent work."],"question":"Which idea is taught in the stage \"Meet the character\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Setting means where and when a story takes place. Details such as heat, shadows and signs help readers picture the scene. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Setting means where and when a story takes place. Details such as heat, shadows and signs help readers picture the scene.","A mood word alone does not reliably establish a physical setting.","Copy the model word-for-word and call that independent work.","Treat a missing detail as a stated fact."],"question":"Which idea is taught in the stage \"Build a setting from clues\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"A plot is not just a list of actions: usually one event creates a problem or changes what a character does next. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["A plot is not just a list of actions: usually one event creates a problem or changes what a character does next.","If events could be shuffled with no effect, explain what links them.","Treat a missing detail as a stated fact.","Skip the prompt because the first idea sounded good."],"question":"Which idea is taught in the stage \"Follow the plot as cause and effect\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Character, setting and plot work together: what a character wants in a particular place helps create the events. Cite evidence from the text. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Character, setting and plot work together: what a character wants in a particular place helps create the events. Cite evidence from the text.","Do not invent a missing ending and present it as a stated event.","Skip the prompt because the first idea sounded good.","Ignore the words and invent a more exciting event."],"question":"Which idea is taught in the stage \"Explain the three elements together\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"The koala is the character; it may need water or cooler weather. The goal is an inference, not a fact unless the text says so. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["The koala is the character; it may need water or cooler weather. The goal is an inference, not a fact unless the text says so.","A narrator and a character are not automatically the same person.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"In \"The koala waited for rain\", name the character and one likely goal.\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"At midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["At midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere.","A mood word alone does not reliably establish a physical setting.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Find a place and time clue in \"At midnight, lanterns glowed outside the campsite\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Dad acts because the storm damaged the rope; the second event responds to the problem. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["Dad acts because the storm damaged the rope; the second event responds to the problem.","If events could be shuffled with no effect, explain what links them.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Explain why this event follows the first: \"A storm snapped the tent rope. Dad gr\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Anya is the character; the fair is the setting; she loses then finds her ticket. The loss causes the search. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["Anya is the character; the fair is the setting; she loses then finds her ticket. The loss causes the search.","Do not invent a missing ending and present it as a stated event.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Identify character, setting and connected events: \"At the fair, Anya dropped her\", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Meaningful understanding is shown when a learner transfers the method to new text or speech and explains their evidence.","marking_guide":"Require an original relevant example, accurate terminology and an explanation grounded in the example.","question":"Use your own example to demonstrate character and explain the evidence supporting your choice.","sample_answer":"Original demonstration: In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision to search starts the action.","type":"short_answer"},{"explanation":"Explaining a correction helps the learner distinguish an effective strategy from a plausible-sounding but inaccurate approach.","marking_guide":"Require a genuine relevant error, accurate correction and a reason that refers to the target concept.","question":"Identify and correct a common mistake relating to plot in this lesson.","sample_answer":"Common error: If events could be shuffled with no effect, explain what links them. Correction: Dad acts because the storm damaged the rope; the second event responds to the problem.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w02-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise character.","Read the mission before you start writing or speaking.","Your goal is: Recognise how characters, settings and connected events create a complete narrative."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: At midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision to search starts the "],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: If events could be shuffled with no effect, explain what links them."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Recognise how characters, settings and connected events create a complete narrative."],"teach0":["Focus on meet the character.","Hold this teaching point: A character is a person, animal or imagined being who takes part in a story. Look for what a character wants and does, n","Worked comparison: The koala is the character; it may need water or cooler weather. The goal is an inference, not a fact unless the text sa"],"teach1":["Focus on build a setting from clues.","Hold this teaching point: Setting means where and when a story takes place. Details such as heat, shadows and signs help readers picture the scene","Worked comparison: At midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere."],"teach2":["Focus on follow the plot as cause and effect.","Hold this teaching point: A plot is not just a list of actions: usually one event creates a problem or changes what a character does next.","Worked comparison: Dad acts because the storm damaged the rope; the second event responds to the problem."],"teach3":["Focus on explain the three elements together.","Hold this teaching point: Character, setting and plot work together: what a character wants in a particular place helps create the events. Cite ev","Worked comparison: Anya is the character; the fair is the setting; she loses then finds her ticket. The loss causes the search."],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Read this original text: \"At the town garden, Noor planted a sunflower seed. A curious crow uncovered it. Noor placed smooth stones around the pot, and the seed"]},"subject":"English","success_criteria":["I can use character with a specific example from this lesson.","I can identify setting and point to the words or events that support it.","I can practise plot independently on a new prompt.","I can notice evidence needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying character independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to meet the character?","type":"multiple_choice"},"example":"WATCH MY THINKING\nIn \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision to search starts the action.\n\nYOUR SMALL TRY\nIn \"The koala waited for rain\", name the character and one likely goal.\n\nCOMPARE AND CORRECT\nThe koala is the character; it may need water or cooler weather. The goal is an inference, not a fact unless the text says so.","explain":"A character is a person, animal or imagined being who takes part in a story. Look for what a character wants and does, not only a name.\n\nA character is a person, animal or imagined being who takes part in a story. Look for what a character wants and does, not only a name. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA narrator and a character are not automatically the same person. Re-read the prompt and correct the misunderstanding before moving on.","title":"Meet the character","visual":[{"alt":"Character Aria searching for a compass contrasted with jetty setting clues before sunrise.","caption":"A character wants something; setting tells where and when that wanting happens.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Character + goal</text><text x=\"28\" y=\"78\">Aria searches for a compass</text><text x=\"358\" y=\"42\">Setting clues</text><text x=\"358\" y=\"78\">before sunrise on a jetty</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision t Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision t Then write your own attempt."}}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying setting independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to build a setting from clues?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"Before sunrise, the jetty was slippery with sea spray\" tells time (before sunrise) and place (the jetty). Both influence what characters can safely do.\n\nYOUR SMALL TRY\nFind a place and time clue in \"At midnight, lanterns glowed outside the campsite\".\n\nCOMPARE AND CORRECT\nAt midnight is the time; outside the campsite locates the scene. The lanterns contribute atmosphere.","explain":"Setting means where and when a story takes place. Details such as heat, shadows and signs help readers picture the scene.\n\nSetting means where and when a story takes place. Details such as heat, shadows and signs help readers picture the scene. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA mood word alone does not reliably establish a physical setting. Re-read the prompt and correct the misunderstanding before moving on.","title":"Build a setting from clues","visual":[{"alt":"Plot linked as a lost library book causing a search of the bus and a recovery.","caption":"Plot is cause and effect, not a shuffled list of actions.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Problem</text><text x=\"28\" y=\"78\">library book is lost</text><text x=\"358\" y=\"42\">Response</text><text x=\"358\" y=\"78\">search the bus then find it</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying plot independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to follow the plot as cause and effect?","type":"multiple_choice"},"example":"WATCH MY THINKING\nMika loses the library book (problem), searches the bus (response), and finds it with the driver (resolution). The search happens because of the loss.\n\nYOUR SMALL TRY\nExplain why this event follows the first: \"A storm snapped the tent rope. Dad grabbed the spare rope.\"\n\nCOMPARE AND CORRECT\nDad acts because the storm damaged the rope; the second event responds to the problem.","explain":"A plot is not just a list of actions: usually one event creates a problem or changes what a character does next.\n\nA plot is not just a list of actions: usually one event creates a problem or changes what a character does next. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nIf events could be shuffled with no effect, explain what links them. Re-read the prompt and correct the misunderstanding before moving on.","title":"Follow the plot as cause and effect"},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying evidence independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to explain the three elements together?","type":"multiple_choice"},"example":"WATCH MY THINKING\n\"At the rocky beach, Eli chased his escaping bucket and caught it before the tide.\" Character: Eli. Setting: rocky beach and rising tide. Plot: bucket escapes, Eli chases and retrieves it.\n\nYOUR SMALL TRY\nIdentify character, setting and connected events: \"At the fair, Anya dropped her ticket but found it under a bench.\"\n\nCOMPARE AND CORRECT\nAnya is the character; the fair is the setting; she loses then finds her ticket. The loss causes the search.","explain":"Character, setting and plot work together: what a character wants in a particular place helps create the events. Cite evidence from the text.\n\nCharacter, setting and plot work together: what a character wants in a particular place helps create the events. Cite evidence from the text. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nDo not invent a missing ending and present it as a stated event. Re-read the prompt and correct the misunderstanding before moving on.","title":"Explain the three elements together"}],"title":"Year 3, Week 2, Lesson 1: Story elements: character, setting and plot","unit_number":1,"unit_title":"Narrative: story elements and planning","week":2,"week_in_unit":2,"word_challenges":null,"worked_example":"I DO — In \"Aria searched for her missing compass\", Aria is the character and recovering the compass is her goal. Her decision to search starts the action.\n\nNow look for the exact evidence in the words or actions. \"Before sunrise, the jetty was slippery with sea spray\" tells time (before sunrise) and place (the jetty). Both influence what characters can safely do.","worked_visuals":[{"alt":"Character Aria searching for a compass contrasted with jetty setting clues before sunrise.","caption":"A character wants something; setting tells where and when that wanting happens.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Character + goal</text><text x=\"28\" y=\"78\">Aria searches for a compass</text><text x=\"358\" y=\"42\">Setting clues</text><text x=\"358\" y=\"78\">before sunrise on a jetty</text></g></svg>"},{"alt":"Plot linked as a lost library book causing a search of the bus and a recovery.","caption":"Plot is cause and effect, not a shuffled list of actions.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Problem</text><text x=\"28\" y=\"78\">library book is lost</text><text x=\"358\" y=\"42\">Response</text><text x=\"358\" y=\"78\">search the bus then find it</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w02-l1' AND family_id IS NULL;
